<?php
require __DIR__.'/config/config.php';

// ---------- Actions ----------
if ((isset($_GET['page']) && $_GET['page']==='logout') || (($_SERVER['REQUEST_METHOD'] ?? '')==='POST' && ($_POST['action'] ?? '')==='logout')) {
    if (current_user()) {
        try { log_action('Logout','Authentication',null,'Sesi pengguna diakhiri'); } catch (Throwable $ignore) {}
    }
    $_SESSION = [];
    if (ini_get('session.use_cookies')) {
        $params = session_get_cookie_params();
        setcookie(session_name(), '', time() - 42000, $params['path'], $params['domain'], $params['secure'], $params['httponly']);
    }
    session_destroy();
    header('Location: index.php'); exit;
}

if ($_SERVER['REQUEST_METHOD']==='POST') {
    $action=$_POST['action']??'';
    try {
        if ($action==='login') {
            $u=trim($_POST['username']??''); $p=$_POST['password']??'';
            $s=db()->prepare('SELECT * FROM users WHERE username=? AND password=? LIMIT 1');
            $s->execute([$u,$p]); $user=$s->fetch();
            if (!$user) { flash('error','Username atau password salah.'); redirect('index.php'); }
            $_SESSION['user']=$user; log_action('Login','Authentication',null,'Login berhasil'); redirect('index.php?page=dashboard');
        }
        require_login();
        if ($action==='save_assessment' && role_can('assessment')) {
            $s=db()->prepare('INSERT INTO assessments(patient_id,officer_id,chief_complaint,consciousness,airway,breathing,circulation,pain_score,fall_risk,nutrition,psychosocial) VALUES (?,?,?,?,?,?,?,?,?,?,?)');
            $s->execute([(int)$_POST['patient_id'],current_user()['id'],$_POST['chief_complaint'],$_POST['consciousness'],$_POST['airway'],$_POST['breathing'],$_POST['circulation'],(int)$_POST['pain_score'],$_POST['fall_risk'],$_POST['nutrition'],$_POST['psychosocial']]);
            log_action('Simpan Assessment','Assessment',(int)$_POST['patient_id'],'Assessment awal keperawatan disimpan'); flash('success','Assessment keperawatan berhasil disimpan.'); redirect('index.php?page=assessment&patient='.(int)$_POST['patient_id']);
        }
        if ($action==='save_vitals' && role_can('vitals')) {
            $s=db()->prepare('INSERT INTO vital_signs(patient_id,officer_id,systolic,diastolic,pulse,respiration,temperature,spo2,height_cm,weight_kg) VALUES (?,?,?,?,?,?,?,?,?,?)');
            $s->execute([(int)$_POST['patient_id'],current_user()['id'],(int)$_POST['systolic'],(int)$_POST['diastolic'],(int)$_POST['pulse'],(int)$_POST['respiration'],(float)$_POST['temperature'],(int)$_POST['spo2'],(float)$_POST['height_cm'],(float)$_POST['weight_kg']]);
            log_action('Input Vital Sign','Vital Sign',(int)$_POST['patient_id'],'Vital sign dicatat'); flash('success','Vital sign tersimpan dengan timestamp petugas.'); redirect('index.php?page=vitals&patient='.(int)$_POST['patient_id']);
        }
        if ($action==='save_note' && role_can('notes')) {
            $s=db()->prepare('INSERT INTO nursing_notes(patient_id,officer_id,note_type,condition_text,intervention_text,response_text,education_text) VALUES (?,?,?,?,?,?,?)');
            $s->execute([(int)$_POST['patient_id'],current_user()['id'],$_POST['note_type'],$_POST['condition_text'],$_POST['intervention_text'],$_POST['response_text'],$_POST['education_text']]);
            log_action('Simpan Nursing Note','Nursing Note',(int)$_POST['patient_id'],'Catatan keperawatan disimpan'); flash('success','Nursing note berhasil disimpan.'); redirect('index.php?page=notes&patient='.(int)$_POST['patient_id']);
        }
        if ($action==='admin_med') {
            $newStatus=$_POST['status'];
            $s=db()->prepare('UPDATE medications SET status=?, administered_by=?, given_at=? WHERE id=?');
            $given=$newStatus==='Given'?date('Y-m-d H:i:s'):null;
            $s->execute([$newStatus,current_user()['id'],$given,(int)$_POST['med_id']]);
            log_action('Update Status Obat', 'Medication',(int)$_POST['med_id'],'Status menjadi '.$newStatus);
            flash('success','Status obat berhasil diperbarui.'); redirect('index.php?page=medications');
        }
        if ($action==='save_monitoring' && role_can('monitoring')) {
            $s=db()->prepare('INSERT INTO monitoring(patient_id,officer_id,parameter_name,parameter_value,note) VALUES (?,?,?,?,?)');
            $s->execute([(int)$_POST['patient_id'],current_user()['id'],$_POST['parameter_name'],$_POST['parameter_value'],$_POST['note']]);
            log_action('Input Monitoring','Monitoring',(int)$_POST['patient_id'],'Parameter '.$_POST['parameter_name'].' dicatat'); flash('success','Parameter monitoring berhasil dicatat.'); redirect('index.php?page=monitoring&patient='.(int)$_POST['patient_id']);
        }
    } catch (Throwable $e) { error_log('[NURSING-SIMRS] '.$e->getMessage()); flash('error','Transaksi tidak dapat diproses. Silakan periksa data dan coba lagi.'); redirect('index.php'); }
}

if (!current_user()):
$flash=take_flash();
