function nav_active($p){ return (($_GET['page']??'dashboard')===$p?'active':''); }
function page_title($p){ return match($p){ 'dashboard'=>'Ringkasan Keperawatan','patients'=>'Daftar Pasien','assessment'=>'Assessment Keperawatan','vitals'=>'Tanda Vital','notes'=>'Catatan Keperawatan','medications'=>'Pemberian Obat','monitoring'=>'Monitoring Pasien','audit'=>'Riwayat Aktivitas','doctor'=>'Tampilan Klinis Dokter','pharmacy'=>'Monitoring Farmasi','admin'=>'Administrasi Sistem', default=>'Nursing SIMRS'}; }
function initials(string $name): string { $parts=preg_split('/\s+/',trim($name)); $letters=''; foreach(array_slice($parts,0,2) as $part){ if($part!=='') $letters.=mb_strtoupper(mb_substr($part,0,1)); } return $letters ?: 'U'; }
function nav_icon(string $name): string { return match($name){ 'dashboard'=>'⌂','patients'=>'♙','assessment'=>'☷','vitals'=>'♥','notes'=>'▤','medications'=>'▱','monitoring'=>'◌','doctor'=>'◈','pharmacy'=>'▥','admin'=>'⚙','audit'=>'↺', default=>'•'}; }

