$recentNotes=$pdo->query('SELECT n.*,p.full_name,u.full_name officer FROM nursing_notes n JOIN patients p ON p.id=n.patient_id JOIN users u ON u.id=n.officer_id ORDER BY note_date DESC LIMIT 6')->fetchAll();
