<script>
(function(){
  const clock=document.getElementById('liveClock');
  if(clock){ setInterval(function(){ const d=new Date(); const f=[d.getHours(),d.getMinutes(),d.getSeconds()].map(v=>String(v).padStart(2,'0')).join(':'); clock.textContent=f; },1000); }
  const p=document.querySelector('.profile'); const c=document.querySelector('.profile-caret');
  if(c && p){ c.addEventListener('click',function(e){ e.stopPropagation(); p.classList.toggle('open'); }); document.addEventListener('click',function(){ p.classList.remove('open'); }); }
})();
</script></body></html>
